  function api(path,opt={}){const identity=JSON.stringify(expected());return fetch(path,{credentials:'same-origin',...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}}).then(async response=>{const body=await response.json().catch(()=>({}));if(identity!==JSON.stringify(expected()))throw new Error('Session changed');if(!response.ok||body.success===false){const error=new Error(body.error||'Request failed');error.status=response.status;throw error;}return body.result??body;});}
  function expected(){return {expected_tenant_id:member?.tenant_id,expected_user_id:member?.telegram_id};}

  function stamp(value){return value?new Date(value).toLocaleString({ru:'ru-RU',az:'az-AZ',en:'en-GB'}[lang()]):'—';}
  function channelName(id){return channels.find(channel=>String(channel.channel_id)===String(id))?.name||String(id||'—');}
