  function notice(message){const node=$('casesNotice');if(!node)return;node.textContent=message||'';node.classList.toggle('show',!!message);}
  function populateChannels(){const node=$('casesChannel');if(!node)return;node.innerHTML=`<option value="">${t('choose')}</option>`+channels.filter(c=>c.provider==='connect').map(c=>`<option value="${esc(c.channel_id)}">${esc(c.name)}</option>`).join('');}
