    const keys=message=>[message.id,message.external_id,...(message.sources||[]).map(source=>source.external_id)].filter(value=>value!=null).map(String);
    const rows=caseHistory.filter(message=>keys(message).some(value=>sourceIds.has(value))).slice().sort((a,b)=>new Date(a.happened_at||a.created_at||0)-new Date(b.happened_at||b.created_at||0));
    const label=message=>{const type=String(message.message_type||message.type||'').toLowerCase(),preview=conversationText(message)||[message.media_filename,caseMessageType(type)].filter(Boolean).join(' · ');return `${conversationName(message,conversationRole(message))} · ${stamp(message.happened_at||message.created_at)} · ${preview.slice(0,100)}`;};
