    payload.cause_evidence=[...($('caseCauseEvidence')?.selectedOptions||[])].map(option=>{const item=(detail?.evidence||[]).find(value=>String(value.id)===option.value);return {message_id:option.value,quote:String(item?.text||item?.body||'').trim()};});if(payload.cause.status==='confirmed'&&!payload.cause_evidence.length){detailNotice(supportCaseText('cause_evidence_required'));return;}try{const result=await api(base+'/'+selected.id,{method:'PATCH',body:JSON.stringify(payload)});selected=result.candidate;detail=result;detailDirty=false;showCard();detailNotice(u('saved'));await load();}catch(error){reviewError(error);}
