  async function review(action,clarificationNote=''){if(detailDirty){detailNotice(rt('saveFirst'));return;}const payload={...expected(),expected_version:selected.version};if(action==='clarify'){const note=String(clarificationNote||'').trim();if(!note){$('[data-clarification-error]').textContent=u('clarificationMissing');return;}payload.clarification_note=note;}if(action==='approve'){payload.agent_ids=[...document.querySelectorAll('#caseAgents input:checked')].map(n=>n.value);if(!payload.agent_ids.length){const picker=$('caseAgentPicker');if(picker)picker.hidden=false;detailNotice(u('agentRequired'));return;}}try{await api(base+'/'+selected.id+'/'+action,{method:'POST',body:JSON.stringify(payload)});clearCaseMedia();$('supportCaseModal')?.remove();detailDirty=false;clarificationDirty=false;await load();}catch(error){if(action==='clarify') $('[data-clarification-error]').textContent=error.message;else reviewError(error);}}
  async function improve(){
    if(detailDirty){detailNotice(rt('saveFirst'));return;}
    const cardId=selected.id,version=selected.version,modal=$('supportCaseModal'),button=modal.querySelector('[data-case-improve]');
    const mode=selected.content_language&&selected.content_language!=='az'?'translate':'improve';
    if(mode==='translate'&&!window.confirm(u('oldAzPreviewConfirm')))return;
    const payload={...expected(),expected_version:version,language:'az',mode,clarifications:$('caseImproveNotes').value};
    const signature=JSON.stringify([cardId,payload]);if(improveRequest?.signature!==signature)improveRequest={signature,id:crypto.randomUUID()};payload.request_id=improveRequest.id;button.disabled=true;
    try{const result=await api(base+'/'+cardId+'/improve',{method:'POST',body:JSON.stringify(payload)});if(!modal.isConnected||selected.id!==cardId||selected.version!==version)return;
      if(!result.proposal||result.candidate_id!==cardId||result.expected_version!==version){detailNotice(rt('noProposal'));return;}
      const proposal=result.proposal,host=$('caseProposal');
      if(mode==='translate'){
        const rows=[['title','caseTitle'],['symptoms','caseSymptoms'],['operator_actions','caseActions'],['resolution_steps','caseSteps'],['cause','caseCause'],['outcome','caseOutcome'],['clarification_note','caseClarificationNote']];
        const valueOf=(object,key)=>key==='title'?object.title:key==='symptoms'?(object.symptoms||[]).join('\n'):key==='operator_actions'?(object.operator_actions||[]).join('\n'):key==='resolution_steps'?(object.resolution_steps||[]).join('\n'):key==='cause'?object.cause?.text||'':key==='clarification_note'?object.clarification_note||'':object.outcome?.text||'';
        host.innerHTML=`<h3>${rt('proposal')}</h3><p>${rt('protected')}</p>${rows.map(([key])=>`<details><summary>${u(key==='title'?'caseName':key==='symptoms'?'symptoms':key==='operator_actions'?'actions':key==='resolution_steps'?'resolution':key==='cause'?'additional':key==='clarification_note'?'clarificationField':'outcome')}</summary><del>${esc(valueOf(selected,key))}</del><p>${esc(valueOf(proposal,key))}</p></details>`).join('')}<button type="button" class="outline" data-apply-proposal>${rt('apply')}</button>`;
        host.querySelector('button').onclick=()=>{if(selected.id!==cardId||selected.version!==version)return;if(detailDirty){detailNotice(rt('saveFirst'));return;}$('caseTitle').value=proposal.title;$('caseSymptoms').value=(proposal.symptoms||[]).join('\n');$('caseActions').value=(proposal.operator_actions||[]).join('\n');$('caseSteps').value=(proposal.resolution_steps||[]).join('\n');$('caseCause').value=proposal.cause?.text||'';$('caseOutcome').value=proposal.outcome?.text||'';pendingContentLanguage='az';pendingClarificationNote=proposal.clarification_note||'';const clarification=modal.querySelector('[data-clarification-note]');if(clarification)clarification.value=pendingClarificationNote;markDirty();host.innerHTML='';};
      }else{
        const rows=[['Başlıq',selected.title,proposal.title],['Əlamətlər',(selected.symptoms||[]).join('\n'),(proposal.symptoms||[]).join('\n')],['Səbəb',selected.cause?.text||'',proposal.cause?.text||''],['Görülən işlər',(selected.operator_actions||[]).join('\n'),(proposal.operator_actions||[]).join('\n')],['Həll yolu',(selected.resolution_steps||[]).join('\n'),(proposal.resolution_steps||[]).join('\n')],['Nəticə',selected.outcome?.text||'',proposal.outcome?.text||'']];
        host.innerHTML=`<h3>${rt('proposal')}</h3><p>${rt('protected')}</p>${rows.map(([label,before,after])=>`<section><strong>${esc(label)}</strong><del>${esc(before||'—')}</del><p>${esc(after||'—')}</p></section>`).join('')}<button type="button" class="outline" data-apply-proposal>${rt('apply')}</button>`;
        host.querySelector('button').onclick=()=>{if(selected.id!==cardId||selected.version!==version)return;if(detailDirty){detailNotice(rt('saveFirst'));return;}$('caseTitle').value=proposal.title;$('caseSymptoms').value=(proposal.symptoms||[]).join('\n');$('caseCause').value=proposal.cause?.text||'';$('caseActions').value=(proposal.operator_actions||[]).join('\n');$('caseSteps').value=(proposal.resolution_steps||[]).join('\n');$('caseOutcome').value=proposal.outcome?.text||'';pendingContentLanguage='az';markDirty();host.innerHTML='';};
      }
    }catch(error){if(modal.isConnected)detailNotice(error.message);}finally{if(modal.isConnected)button.disabled=false;}
  }
  function dateValue(date){const value=new Date(date);value.setMinutes(value.getMinutes()-value.getTimezoneOffset());return value.toISOString().slice(0,10);}
  function setPeriodPreset(){const preset=$('casesPeriodPreset'),from=$('casesFrom'),to=$('casesTo');if(!preset)return;const days=Number(preset.value);const custom=!days;from.disabled=!custom;to.disabled=!custom;if(custom)return;const end=new Date(),start=new Date(end);start.setDate(start.getDate()-(days-1));from.value=dateValue(start);to.value=dateValue(end);}
  function bind(){const controls=document.querySelector('.support-cases-controls');if(controls&&!$('casesPeriodPreset')){const label=document.createElement('label');label.innerHTML=`${ct('periodPreset')}<select id="casesPeriodPreset"><option value="7">${ct('last7')}</option><option value="30">${ct('last30')}</option><option value="0">${ct('custom')}</option></select>`;controls.insertBefore(label,$('casesFrom').parentElement);}setPeriodPreset();$('casesPeriodPreset').onchange=setPeriodPreset;$('casesChannel').onchange=()=>{populateConversations();batchId=null;batchState=null;load();};$('casesConversation').onchange=()=>{batchId=null;batchState=null;load();};$('casesLoad').onclick=()=>{batchId=null;batchState=null;load();};$('casesStatus').onchange=()=>load();$('casesMore').onclick=()=>load(true);$('casesAnalyse').onclick=analyse;}
  async function prepare(){if(!member||!root())return;clearTimeout(pollTimer);generation++;batchId=null;batchState=null;cards=[];nextBefore=null;render();try{const results=await Promise.all([api('/api/platform/ai/dialogs'),api('/api/platform/ai/agents'),api('/api/platform/ai/channels?'+new URLSearchParams(expected()))]);dialogs=results[0].dialogs||[];agents=Array.isArray(results[1])?results[1]:results[1].agents||[];channels=results[2].channels||[];populateChannels();await load();await window.TenantKnowledgeCampaigns?.mount(root(),{channels,agents,api,expected,lang,refreshCards:()=>load()});}catch(error){notice(error.message);}}
  document.addEventListener('tenant-profile',event=>{caseReturnPending=false;clearTimeout(pollTimer);generation++;$('supportCaseModal')?.remove();cards=[];dialogs=[];channels=[];agents=[];selected=null;detail=null;batchRequest=null;batchId=null;batchState=null;if(root())root().innerHTML='';member=event.detail?.member||null;if(member&&['owner','admin'].includes(member.role))prepare();});
